grep -r "CompilerPassInterface" /Users/ethanhinson/dev/code-indexer/bench/repos --include="*.php" 2>/dev/null | cut -d: -f1 | sort -u | while read file; do
  # Check if file is in a member project (not vendor, node_modules, dist, build)
  case "$file" in
    */vendor/*|*/node_modules/*|*/dist/*|*/build/*) continue ;;
    */btt-api/*) continue ;;
    */btt-ws/*) continue ;;
    */btt-ws-private/*) continue ;;
    */gin/*) continue ;;
    */vscode/*) continue ;;
    */wordpress/*) continue ;;
  esac

  # Must be in a member project directory
  if [[ "$file" =~ /(client_golang|drupal|flask|laravel-framework|nest|prometheus|symfony|werkzeug)/ ]]; then
    echo "$file"
  fi
done

